package app.loveu;
import java.time.*;import java.util.*;
public final class PeriodAnalysisTest {
 static void check(boolean c){if(!c)throw new AssertionError();}static PeriodAnalysis.Entry e(String s,String end){return new PeriodAnalysis.Entry(s,end);}static void bad(PeriodAnalysis.Entry e,List<PeriodAnalysis.Entry> all){try{PeriodAnalysis.validate(e,all,LocalDate.of(2026,10,12));throw new AssertionError("accepted invalid dates");}catch(IllegalArgumentException expected){}}
 public static void main(String[] args){List<PeriodAnalysis.Entry> all=Arrays.asList(e("2026-01-01","2026-01-05"),e("2026-01-29","2026-02-02"),e("2026-03-01","2026-03-05"));String s=PeriodAnalysis.summary(all,LocalDate.of(2026,10,12));check(s.contains("平均经期 5.0 天")&&s.contains("周期中位数 29.5 天")&&s.contains("2026-03-29 ～ 2026-04-01"));bad(e("2026-01-04","2026-01-08"),all);bad(e("2026-10-13",null),all);bad(e("2026-10-10","2026-10-09"),all);bad(e("2026-10-10",null),Arrays.asList(e("2026-10-01",null)));PeriodAnalysis.validate(e("2026-01-06","2026-01-07"),Arrays.asList(all.get(0)),LocalDate.of(2026,10,12));check(!PeriodAnalysis.summary(Arrays.asList(all.get(0)),LocalDate.now()).contains("下次预计"));List<PeriodAnalysis.Entry> reversed=new ArrayList<>(all);Collections.reverse(reversed);check(s.equals(PeriodAnalysis.summary(reversed,LocalDate.of(2026,10,12))));check(reversed.get(0).start.equals("2026-03-01"));System.out.println("PeriodAnalysisTest PASS inclusive durations, median, uncertainty, sparse sample, overlap, future, reversed dates, input retention");}
}
